// Capturar datos de cada nodo de Google Sheets
// Ajusta los nombres de los nodos dentro de $items() si en tu lienzo se llaman de otra forma
const configData = $items('Leer Config').map(i => i.json)[0] || {};
const Usuarios = $items('Leer Usuarios').map(i => i.json);
const registros = $items('Leer Registros').map(i => i.json);
const reservas = $items('Leer Reservas').map(i => i.json);
const mudanzas = $items('Leer Mudanzas').map(i => i.json);
const paquetes = $items('Leer Paquetes').map(i => i.json);

// Convertir campos numéricos de configuración para evitar errores de tipo en la app
const configSaneada = {
  tarifaCarro: Number(configData.tarifaCarro) || 3000,
  tarifaMoto: Number(configData.tarifaMoto) || 1500,
  tarifaSalonSocial: Number(configData.tarifaSalonSocial) || 150000,
  tarifaZonaBbq: Number(configData.tarifaZonaBbq) || 50000,
  tarifaCancha: Number(configData.tarifaCancha) || 20000,
  correoDestino: configData.correoDestino || 'admin@conjunto.com'
};

// Formatear la respuesta exacta que consumirá la PWA
return [{
  json: {
    Usuarios: Usuarios,
    registros: registros,
    reservas: reservas,
    mudanzas: mudanzas,
    paquetes: paquetes,
    config: configSaneada
  }
}];

